import {BOSS_GEAR,GEAR_ERAS,GEAR_SLOTS,bossGearState,gearEra,gearStats,gearBonuses,equipBossGear,unequipBossGear,reforgeInheritedGear} from './boss-gear.js?v=5.16.0';
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
const label={power:'Attack',magic:'Magic',maxHp:'HP',maxMp:'MP',speed:'Tempo'},stats=b=>Object.entries(b).map(([k,v])=>'+'+(k==='speed'?v.toFixed(3):v)+' '+label[k]).join(' · ')||'No added stats';
const effects={origin:'Physical attacks against armor gain 4%.',present:'Matching element hits gain 4%.',aftermath:'Hits against exposed targets gain 4%.'};
export function bossGearMenu(world,onSave,onBack){const root=el('section');root.className='guardian-forge';let hero=world.state.party[0],era=gearEra(world.state),filter='all';function paint(){const s=world.state,p=bossGearState(s),h=s.heroes[hero];root.replaceChildren();root.append(el('h3','The Guardian Inheritance'),el('p','Recovered parts become tools for another life. Three equipment slots; one copy of each item across the crew. Historical forms change stats and tactics, not the world’s date.'));
 const nav=el('nav');for(const id of s.recruited){const b=el('button',s.heroes[id].name);b.setAttribute('aria-pressed',String(id===hero));b.onclick=()=>{hero=id;paint();};nav.append(b);}root.append(nav);
 const sum=el('article');sum.className='guardian-summary';sum.append(el('h4',h.name+' · current gear'),el('strong',stats(gearBonuses(s,h))));for(const slot of GEAR_SLOTS){const worn=h.guardianGear?.[slot],g=BOSS_GEAR.find(g=>g.id===worn?.id),row=el('p',slot.toUpperCase()+' · '+(g?g.name+' / '+worn.era:'Empty'));if(g){const b=el('button','Remove');b.disabled=s.mode==='battle';b.onclick=()=>{unequipBossGear(s,hero,slot);onSave();paint();};row.append(b);}sum.append(row);}root.append(sum);
 const controls=el('div'),formLabel=el('label','Historical form '),select=el('select');for(const e of GEAR_ERAS){const o=el('option',e[0].toUpperCase()+e.slice(1));o.value=e;select.append(o);}select.value=era;select.onchange=()=>{era=select.value;paint();};formLabel.append(select);const slotLabel=el('label',' Show '),slotSelect=el('select');for(const slot of ['all',...GEAR_SLOTS]){const o=el('option',slot);o.value=slot;slotSelect.append(o);}slotSelect.value=filter;slotSelect.onchange=()=>{filter=slotSelect.value;paint();};slotLabel.append(slotSelect);controls.append(formLabel,slotLabel);root.append(controls,el('p',effects[era]+' Each piece also resists its element by 6%. Total gear hit bonus caps at 12%; resistance at 18%.'));
 const grid=el('div');grid.className='guardian-cards';for(const g of BOSS_GEAR.filter(g=>p.patterns.includes(g.id)&&(filter==='all'||g.slot===filter))){const card=el('article');card.style.setProperty('--guardian-color',g.color);const icon=el('span',({weapon:'⚔',mantle:'◈',focus:'✦'})[g.slot]);icon.className='guardian-symbol';card.append(icon,el('small','Guardian '+g.chapter+' · '+g.slot+' · '+g.core),el('h4',g.name),el('p',g.lore),el('strong',era+' · '+stats(gearStats(s,g,era))));if(g.rule){const rule=el('p',g.rule.name+' · '+g.rule.detail);rule.className='guardian-rule';card.append(rule);}const current=h.guardianGear?.[g.slot],old=BOSS_GEAR.find(x=>x.id===current?.id),before=old?gearStats(s,old,current.era):{},after=gearStats(s,g,era),delta={};for(const k of new Set([...Object.keys(before),...Object.keys(after)])){const v=(after[k]||0)-(before[k]||0);if(v)delta[k]=v;}const compare=Object.entries(delta).map(([k,v])=>(v>0?'+':'')+(k==='speed'?v.toFixed(3):v)+' '+label[k]).join(' · ');card.append(el('p','Compared with this slot: '+(compare||'same stats')));const own=p.owned.includes(g.id),wearer=s.heroes.find(a=>Object.values(a.guardianGear||{}).some(v=>v?.id===g.id)),b=el('button',own?(wearer&&wearer!==h?'Worn by '+wearer.name:'Equip '+era+' form'):'Reforge pattern · '+(40+g.chapter*5)+' credits');b.disabled=s.mode==='battle'||(own?!!wearer&&wearer!==h:s.chapter<Math.min(g.chapter,6)||!s.story?.weapon||s.gold<40+g.chapter*5);b.onclick=()=>{if(own?equipBossGear(s,hero,g.id,era):reforgeInheritedGear(s,g.id)){onSave();paint();}};card.append(b);grid.append(card);}if(!grid.children.length)grid.append(el('p','Defeat a guardian to recover its equipment pattern. Existing victories are remembered.'));root.append(grid,el('p','Origins favor raw strength and endurance; present forms balance power and focus; aftermath forms favor magic, MP and tempo. Later patterns reforge at chapter 6 at the latest, but their stats scale down to this journey’s chapter. Changing or removing gear never restores HP or MP.'));
 const back=el('button','Back to pause');back.onclick=onBack;root.append(back);}paint();return root;}
